type imdsDoFunc func(*http.Request) (*http.Response, error)

func (fn imdsDoFunc) Do(request *http.Request) (*http.Response, error) {
	return fn(request)
}

func imdsDescriptorFixture(t *testing.T) []byte {
	t.Helper()
	wire, err := (hostboot.Descriptor{
		SchemaVersion: hostboot.SchemaVersion,
		Cell:          "gru", Region: "GRU", Node: "host-0123456789abcdef01234567", Owner: "terrascale",
		FleetGeneration: 7, CreateKey: "0000000000AVXGCP7NEZ0TK93A",
		ImageID: "ocid1.image.oc1.sa-saopaulo-1.image-a", DatabaseID: "0000000000WVSMBJNMAWCDJBSK",
		PartitionID: "0000000000Z3WK359G2W66CVT8", SeatID: "000000000082AXF7GZQT1D126Y", HostAttempt: 2, IntentGeneration: 9,
		IntentPayloadDigest: strings.Repeat("a", 64), CanonicalRosterDigest: strings.Repeat("b", 64),
		ManagedHostProfileDigest: strings.Repeat("c", 64), RuntimeManifestDigest: strings.Repeat("d", 64),
	}).CanonicalBytes()
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func imdsResponse(status int, body []byte, contentLength int64) *http.Response {
	return &http.Response{StatusCode: status, ContentLength: contentLength,
		Body: io.NopCloser(bytes.NewReader(body)), Header: make(http.Header)}
}

const (
	imdsInstanceURL   = "http://169.254.169.254/opc/v2/instance/id"
	imdsNameURL       = "http://169.254.169.254/opc/v2/instance/displayName"
	imdsDescriptorURL = "http://169.254.169.254/opc/v2/instance/metadata/" + hostboot.MetadataKey
	imdsEnrollmentURL = "http://169.254.169.254/opc/v2/instance/metadata/" + hostboot.EnrollmentMetadataKey
	// imdsBootstrapURL is the controller launch hint naming its signed slot.
	imdsBootstrapURL = "http://169.254.169.254/opc/v2/instance/metadata/terrascale-bootstrap"
	imdsNodePoolURL  = "http://169.254.169.254/opc/v2/instance/metadata/" + hostboot.NodePoolMetadataKey
	maxIMDSIDBytes   = 255
)

// ErrNotManagedHost reports an instance launched without a host descriptor,
// such as a controller sharing the qualified image. An operator-launched C#
// TerraBase host carries a static descriptor (hostboot.Static) instead.
var ErrNotManagedHost = errors.New("instance has no managed host descriptor")

// ErrNodeNotNamed reports a node pool instance the regional leader has not
// renamed to its node name yet; host-setup retries until it has.
var ErrNodeNotNamed = errors.New("pool node is not named yet")

type HTTPDoer interface {
	Do(*http.Request) (*http.Response, error)
}

func NewIMDSClient() *http.Client {
	return &http.Client{
		Timeout: 5 * time.Second,
		Transport: &http.Transport{
			Proxy: nil,
		},
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
}

// InstanceMetadata is the untrusted instance identity hint returned by OCI
// IMDSv2. The controller must independently observe the instance and peer IP.
type InstanceMetadata struct {
	InstanceID string
	Descriptor hostboot.Descriptor
	Wire       []byte
}

func ReadInstanceMetadata(ctx context.Context, client HTTPDoer) (InstanceMetadata, error) {
	instanceID, err := readInstanceID(ctx, client)
	if err != nil {
		return InstanceMetadata{}, err
	}
	encoded, err := readIMDS(ctx, client, imdsDescriptorURL, hostboot.MaxDescriptorBytes)
	if errors.Is(err, errIMDSKeyAbsent) {
		return InstanceMetadata{}, ErrNotManagedHost
	}
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("read OCI IMDSv2 host descriptor: %w", err)
	}
	descriptor, err := hostboot.ParseHost(encoded)
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("parse OCI IMDSv2 host descriptor: %w", err)
	}
	return InstanceMetadata{InstanceID: instanceID, Descriptor: descriptor, Wire: encoded}, nil
}

// ReadInstanceID returns this instance's OCID from OCI IMDSv2.
func ReadInstanceID(ctx context.Context, client HTTPDoer) (string, error) {
	return readInstanceID(ctx, client)
}

func readInstanceID(ctx context.Context, client HTTPDoer) (string, error) {
	if client == nil {
		return "", errors.New("IMDS client is required")
	}
	idWire, err := readIMDS(ctx, client, imdsInstanceURL, maxIMDSIDBytes)
	if err != nil {
		return "", fmt.Errorf("read OCI IMDSv2 instance ID: %w", err)
	}
	instanceID := strings.TrimSpace(string(idWire))
	if !strings.HasPrefix(instanceID, "ocid1.instance.") || len(instanceID) > maxIMDSIDBytes ||
		strings.ContainsAny(instanceID, " \t\r\n\f\v") {
		return "", errors.New("OCI IMDSv2 instance ID is invalid")
	}
	return instanceID, nil
}

// ReadControllerHostMetadata returns the static descriptor of the host agent
// on a controller VM: its instance's display name once that is a node of the
// region (ts-node rename renamed it, TS-609), else the server name of the
// controller's launch slot in cell and region. An instance without a
// controller slot is not a host.
func ReadControllerHostMetadata(ctx context.Context, client HTTPDoer, cell, region string) (InstanceMetadata, error) {
	instanceID, err := readInstanceID(ctx, client)
	if err != nil {
		return InstanceMetadata{}, err
	}
	wire, err := readIMDS(ctx, client, imdsBootstrapURL, 256)
	if errors.Is(err, errIMDSKeyAbsent) {
		return InstanceMetadata{}, ErrNotManagedHost
	}
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("read OCI IMDSv2 controller slot: %w", err)
	}
	var bootstrap struct {
		SchemaVersion int    `json:"schemaVersion"`
		Slot          string `json:"slot"`
	}
	if err := protocol.DecodeStrict(wire, &bootstrap, 256); err != nil || bootstrap.SchemaVersion != 1 {
		return InstanceMetadata{}, errors.New("OCI IMDSv2 controller slot is invalid")
	}
	node, err := naming.RegionCell(region).ControllerSlot(bootstrap.Slot)
	if err != nil {
		return InstanceMetadata{}, err
	}
	// A failed read fails setup: falling back to the slot's name would
	// enroll a renamed node under its old name.
	name, err := readIMDS(ctx, client, imdsNameURL, 256)
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("read OCI IMDSv2 display name: %w", err)
	}
	if displayName := strings.TrimSpace(string(name)); naming.IsNode(displayName, region) {
		node = displayName
	}
	descriptor := hostboot.Static(cell, region, node)
	encoded, err := descriptor.CanonicalBytes()
	if err != nil {
		return InstanceMetadata{}, err
	}
	return InstanceMetadata{InstanceID: instanceID, Descriptor: descriptor, Wire: encoded}, nil
}

// ReadPoolNodeMetadata returns the static descriptor of a node pool instance
// once the regional leader has named it ts-<region>-<n>. Until then OCI's
// inst-… name is no node name, so the instance is ErrNodeNotNamed.
func ReadPoolNodeMetadata(ctx context.Context, client HTTPDoer, cell, region string) (InstanceMetadata, error) {
	instanceID, err := readInstanceID(ctx, client)
	if err != nil {
		return InstanceMetadata{}, err
	}
	wire, err := readIMDS(ctx, client, imdsNodePoolURL, 256)
	if errors.Is(err, errIMDSKeyAbsent) {
		return InstanceMetadata{}, ErrNotManagedHost
	}
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("read OCI IMDSv2 node pool marker: %w", err)
	}
	var marker struct {
		SchemaVersion int `json:"schemaVersion"`
	}
	if err := protocol.DecodeStrict(wire, &marker, 256); err != nil || marker.SchemaVersion != 1 {
		return InstanceMetadata{}, errors.New("OCI IMDSv2 node pool marker is invalid")
	}
	name, err := readIMDS(ctx, client, imdsNameURL, 256)
	if err != nil {
		return InstanceMetadata{}, fmt.Errorf("read OCI IMDSv2 display name: %w", err)
	}
	node := strings.TrimSpace(string(name))
	if !naming.IsNode(node, region) {
		return InstanceMetadata{}, ErrNodeNotNamed
	}
	descriptor := hostboot.Static(cell, region, node)
	encoded, err := descriptor.CanonicalBytes()
	if err != nil {
		return InstanceMetadata{}, err
	}
	return InstanceMetadata{InstanceID: instanceID, Descriptor: descriptor, Wire: encoded}, nil
}

// ReadEnrollmentMetadata reads the exact public enrollment bundle delivered
// by the controller that launched this host.
func ReadEnrollmentMetadata(ctx context.Context, client HTTPDoer) ([]byte, error) {
	if client == nil {
		return nil, errors.New("IMDS client is required")
	}
	wire, err := readIMDS(ctx, client, imdsEnrollmentURL, MaxPublicBundleBytes)
	if err != nil {
		return nil, fmt.Errorf("read OCI IMDSv2 host enrollment bundle: %w", err)
	}
	return wire, nil
}

var errIMDSKeyAbsent = errors.New("OCI IMDSv2 metadata key is absent")

func readIMDS(ctx context.Context, client HTTPDoer, endpoint string, maximum int64) ([]byte, error) {
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	request.Header.Set("Authorization", "Bearer Oracle")
	response, err := client.Do(request)
	if err != nil {
		return nil, err
	}
	if response == nil || response.Body == nil {
		return nil, errors.New("OCI IMDSv2 response is missing")
	}
	defer response.Body.Close()
	if response.StatusCode == http.StatusNotFound {
		return nil, errIMDSKeyAbsent
	}
	if response.StatusCode != http.StatusOK || response.ContentLength > maximum {
		return nil, errors.New("OCI IMDSv2 response is invalid or too large")
	}
	wire, err := io.ReadAll(io.LimitReader(response.Body, maximum+1))
	if err != nil || len(wire) == 0 || int64(len(wire)) > maximum {
		return nil, errors.New("OCI IMDSv2 body is missing or too large")
	}
	return wire, nil
}

hostboot.text:
func Static(cell, region, node string) Descriptor {
	return Descriptor{SchemaVersion: StaticSchemaVersion, Cell: cell, Region: region, Node: node}
}

// IsStatic reports whether the descriptor names a static host.
func (descriptor Descriptor) IsStatic() bool { return descriptor.SchemaVersion == StaticSchemaVersion }

// IsController reports whether a static descriptor names a controller VM.
func (descriptor Descriptor) IsController() bool {
	cell, err := naming.RegionCell(descriptor.Region).Name()
	return descriptor.IsStatic() && err == nil && (strings.HasPrefix(descriptor.Node, cell+"-"+naming.Controller+"-") ||
		strings.HasPrefix(descriptor.Node, regionNode(descriptor.Region)))
}

// regionNode is the prefix of the region's node names, e.g. ts-sfo-.
func regionNode(region string) string { return "ts-" + strings.ToLower(region) + "-" }

// Validate checks the closed v1 identity and digest bindings and the bounded
// canonical wire size. It performs no signature or live-resource checks.
func (descriptor Descriptor) Validate() error {
	_, err := descriptor.CanonicalBytes()
	return err
}

// CanonicalBytes returns the deterministic v1 JSON representation used in OCI
// instance metadata and retry binding.
func (descriptor Descriptor) CanonicalBytes() ([]byte, error) {
	if err := descriptor.validateFields(); err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(descriptor)
	if err != nil {
		return nil, fmt.Errorf("%w: encode canonical JSON: %v", ErrInvalidDescriptor, err)
	}
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return nil, fmt.Errorf("%w: canonical JSON exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	return wire, nil
}

// Digest returns the lowercase SHA-256 digest of CanonicalBytes.
func (descriptor Descriptor) Digest() (string, error) {
	wire, err := descriptor.CanonicalBytes()
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(wire)
	return hex.EncodeToString(digest[:]), nil
}

// Parse decodes one exact canonical v1 managed descriptor. Unknown members,
// duplicate names, oversized input, and alternate noncanonical encodings are
// rejected, and so is a static descriptor.
func Parse(wire []byte) (Descriptor, error) {
	descriptor, err := ParseHost(wire)
	if err == nil && descriptor.IsStatic() {
		return Descriptor{}, fmt.Errorf("%w: a static host is not a managed launch", ErrInvalidDescriptor)
	}
	return descriptor, err
}

// ParseHost decodes one exact canonical managed or static descriptor.
func ParseHost(wire []byte) (Descriptor, error) {
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return Descriptor{}, fmt.Errorf("%w: wire is absent or exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	var descriptor Descriptor
	if err := protocol.DecodeStrict(wire, &descriptor, MaxDescriptorBytes); err != nil {
		return Descriptor{}, fmt.Errorf("%w: decode strict JSON: %v", ErrInvalidDescriptor, err)
	}
	canonical, err := descriptor.CanonicalBytes()
	if err != nil {
		return Descriptor{}, err
	}
	if !bytes.Equal(wire, canonical) {
		return Descriptor{}, fmt.Errorf("%w: wire is not the exact canonical representation", ErrInvalidDescriptor)
	}
	return descriptor, nil
}

func (descriptor Descriptor) validateFields() error {
	if descriptor.IsStatic() {
		cell, err := naming.RegionCell(descriptor.Region).Name()
		number, ok := strings.CutPrefix(descriptor.Node, cell+"-"+naming.Member+"-")
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, cell+"-"+naming.Controller+"-")
		}
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, regionNode(descriptor.Region))
		}
		if pool, isPool := strings.CutPrefix(descriptor.Node, cell+"-pool-"); !ok && isPool {
			// The scheme allows no hyphen in a pool name.
			_, number, ok = strings.Cut(pool, "-")
		}
		if err != nil || !validCellRegion(descriptor.Cell, descriptor.Region) || !ok ||
			naming.Validate(descriptor.Node) != nil || strings.Contains(number, "-") ||
			descriptor != Static(descriptor.Cell, descriptor.Region, descriptor.Node) {
			return fmt.Errorf("%w: static host must name one database, controller, node or pool server of its cell and nothing else", ErrInvalidDescriptor)
		}
		return nil
	}
	if descriptor.SchemaVersion != SchemaVersion || !validCellRegion(descriptor.Cell, descriptor.Region) ||
		!descriptorToken.MatchString(descriptor.Node) || !descriptorToken.MatchString(descriptor.Owner) ||
		!validCreateKey(descriptor.CreateKey) || !descriptorImageID.MatchString(descriptor.ImageID) ||
		descriptor.FleetGeneration == 0 || descriptor.HostAttempt == 0 || descriptor.IntentGeneration == 0 ||
		!entityid.Valid(descriptor.DatabaseID) || !entityid.Valid(descriptor.PartitionID) ||
		!entityid.Valid(descriptor.SeatID) ||
		!descriptorDigest.MatchString(descriptor.IntentPayloadDigest) ||
		!descriptorDigest.MatchString(descriptor.CanonicalRosterDigest) ||
		!descriptorDigest.MatchString(descriptor.ManagedHostProfileDigest) ||
		!descriptorDigest.MatchString(descriptor.RuntimeManifestDigest) {
		return fmt.Errorf("%w: required identity, generation, image, or digest binding", ErrInvalidDescriptor)
	}
	return nil
}

func validCellRegion(cell, region string) bool {
	return catalog.MatchesName(cell, region)
}

func validCreateKey(value string) bool {
	return entityid.Valid(value)
}

naming.text:
func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

func (c Cell) Node(n int) (string, error) {
	return valid(fmt.Sprintf("ts-%s-%d", strings.ToLower(c.Region), n))
}

// Server returns the name of the cell's n-th server of role, e.g. gru-1-ctl-1.
func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// PoolServer returns the name of the n-th host of a node pool, e.g.
// gru-1-pool-app-3. A pool name is 2 to 12 lower-case letters and digits,
// starting with a letter.
func (c Cell) PoolServer(pool string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-pool-%s-%d", strings.ToLower(c.Region), c.Index, pool, n))
}

// ControllerSlot returns the server name of a signed controller slot:
// controller-a, -b and -c are the region's nodes 1, 2 and 3 (ts-sfo-1). GRU
// keeps ctl-1, -2 and -3 (gru-1-ctl-1) until its servers are renamed: a
// controller refuses a NATS store of another server name.
func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

// MemberSlot returns the server name of a regional plan's database host
// slot: member-a and -b are db-1 and -2.
func (c Cell) MemberSlot(slot string) (string, error) { return c.slot(slot, "member-", Member) }

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

func IsNode(name, region string) bool {
	match := nodeScheme.FindStringSubmatch(name)
	return match != nil && match[1] == strings.ToLower(region) && !strings.HasSuffix(name, "-data") &&
		catalog.IsCell(strings.ToUpper(region))
}

issuer.text:
func LoadIssuer(cell, cellAccount, natsSeedPath, keyPath, certPath string, rootPEM []byte) (*Issuer, error) {
	if !validCellRegion(cell, strings.ToUpper(cell)) || !nkeys.IsValidPublicAccountKey(cellAccount) {
		return nil, errors.New("host issuer cell account is invalid")
	}
	seed, err := os.ReadFile(natsSeedPath)
	if err != nil || len(seed) == 0 || len(seed) > 4096 {
		return nil, errors.New("host NATS issuer seed is unavailable")
	}
	defer clear(seed)
	pair, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(seed))))
	if err != nil {
		return nil, fmt.Errorf("parse host NATS issuer seed: %w", err)
	}
	keyPEM, err := os.ReadFile(keyPath)
	if err != nil || len(keyPEM) == 0 || len(keyPEM) > 8192 {
		pair.Wipe()
		return nil, errors.New("host TLS issuer key is unavailable")
	}
	defer clear(keyPEM)
	certPEM, err := os.ReadFile(certPath)
	if err != nil || len(certPEM) == 0 || len(certPEM) > 8192 {
		pair.Wipe()
		return nil, errors.New("host TLS issuer certificate is unavailable")
	}
	var roots []*x509.Certificate
	for rest := rootPEM; ; {
		var block *pem.Block
		if block, rest = pem.Decode(rest); block == nil {
			if len(strings.TrimSpace(string(rest))) != 0 {
				pair.Wipe()
				return nil, errors.New("host TLS regional root has trailing data")
			}
			break
		}
		root, err := x509.ParseCertificate(block.Bytes)
		if block.Type != "CERTIFICATE" || err != nil {
			pair.Wipe()
			return nil, errors.New("host TLS regional root is invalid")
		}
		roots = append(roots, root)
	}
	key, cert, root, err := ParseTLSIssuer(keyPEM, certPEM, roots)
	if err != nil {
		pair.Wipe()
		return nil, err
	}
	return &Issuer{CellAccount: cellAccount, Cell: cell, NATSKey: pair, TLSKey: key, TLSCert: cert, TLSCertPEM: certPEM, Root: root}, nil
}

// ParseTLSIssuer checks the host TLS issuer: one EC key and one certificate,
// each a single PEM block, that match; the certificate is a client-only,
// path-length-zero intermediate signed by one of roots and is not itself a
// root. It returns the root that signed it.
func ParseTLSIssuer(keyPEM, certPEM []byte, roots []*x509.Certificate) (*ecdsa.PrivateKey, *x509.Certificate, *x509.Certificate, error) {
	keyBlock, rest := pem.Decode(keyPEM)
	if keyBlock == nil || keyBlock.Type != "EC PRIVATE KEY" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, nil, nil, errors.New("host TLS issuer key format is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return nil, nil, nil, err
	}
	certBlock, rest := pem.Decode(certPEM)
	if certBlock == nil || certBlock.Type != "CERTIFICATE" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, nil, nil, errors.New("host TLS issuer certificate format is invalid")
	}
	cert, err := x509.ParseCertificate(certBlock.Bytes)
	if err != nil {
		return nil, nil, nil, err
	}
	var signer *x509.Certificate
	for _, root := range roots {
		if root.Equal(cert) {
			return nil, nil, nil, errors.New("host TLS issuer is a regional root")
		}
		if signer == nil && cert.CheckSignatureFrom(root) == nil {
			signer = root
		}
	}
	public, keyIsECDSA := cert.PublicKey.(*ecdsa.PublicKey)
	if signer == nil || cert.CheckSignatureFrom(cert) == nil || !cert.IsCA || !cert.MaxPathLenZero ||
		cert.KeyUsage&x509.KeyUsageCertSign == 0 || len(cert.ExtKeyUsage) != 1 || cert.ExtKeyUsage[0] != x509.ExtKeyUsageClientAuth ||
		!keyIsECDSA || !public.Equal(&key.PublicKey) {
		return nil, nil, nil, errors.New("host TLS issuer is not a root-signed client-only intermediate")
	}
	return key, cert, signer, nil
}

certificate.text:
// Certificate issues template under parent, or self-signed when parent is
// nil, and returns its authority, certificate PEM and key PEM.
func Certificate(t testing.TB, template *x509.Certificate, parent *Authority) (Authority, []byte, []byte) {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	if template.SerialNumber == nil {
		template.SerialNumber, _ = rand.Int(rand.Reader, big.NewInt(1<<62))
	}
	signer, signerKey := template, key
	if parent != nil {
		signer, signerKey = parent.Certificate, parent.Key
	}
	der, err := x509.CreateCertificate(rand.Reader, template, signer, &key.PublicKey, signerKey)
	if err != nil {
		t.Fatal(err)
	}
	certificate, _ := x509.ParseCertificate(der)
	keyDER, _ := x509.MarshalECPrivateKey(key)
	return Authority{Certificate: certificate, Key: key}, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})
}

// CA is a CA template valid from an hour before now until notAfter.
func CA(name string, now, notAfter time.Time) *x509.Certificate {
	return &x509.Certificate{Subject: pkix.Name{CommonName: name}, NotBefore: now.Add(-time.Hour), NotAfter: notAfter,
		IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign}
}

// ControllerIssuer is the controller TLS issuer template under a cell CA.
func ControllerIssuer(now, notAfter time.Time) *x509.Certificate {
	template := CA("TerraScale gru controller issuer", now, notAfter)
	template.MaxPathLenZero = true
	template.ExtKeyUsage = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}
	return template
}

// HostIssuer is the host TLS issuer template of cell gru, as hostenroll loads it.
func HostIssuer(now, notAfter time.Time) *x509.Certificate { return hostIssuer("gru", now, notAfter) }

func hostIssuer(region string, now, notAfter time.Time) *x509.Certificate {
	template := CA("TerraScale "+region+" host issuer", now, notAfter)
	template.MaxPathLenZero = true
	template.ExtKeyUsage = []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
	template.PermittedDNSDomainsCritical = true
	template.PermittedDNSDomains = []string{".hosts." + region + ".terrascale.internal"}
	template.PermittedURIDomains = []string{"hosts." + region + ".terrascale.internal"}
	return template
}

role.text:
func (issuer *Issuer) ValidateRoleScope(raw string) error {
	if issuer == nil || issuer.NATSKey == nil {
		return errors.New("host NATS issuer is unavailable")
	}
	account, err := jwt.DecodeAccountClaims(raw)
	if err != nil || account.Subject != issuer.CellAccount {
		return errors.New("cell account claim is invalid")
	}
	signer, err := roleidentity.Signer(issuer.NATSKey)
	if err != nil {
		return err
	}
	public, err := signer.PublicKey()
	signer.Wipe()
	if err != nil {
		return err
	}
	bound, ok := account.SigningKeys.GetScope(public)
	scope, scoped := bound.(*jwt.UserScope)
	if !ok || !scoped || !reflect.DeepEqual(scope, roleidentity.Scope(public)) {
		return errors.New("the cell account has no role signer; apply ts-orch bootstrap role-claim (docs/broker-claim-rotation.md)")
	}
	return nil
}

// IssueRole issues node's member of role a user JWT for userKey, signed by the
// role signer and tagged with the role's buckets, and a client certificate
// for csrPEM, both expiring together.
func (issuer *Issuer) IssueRole(role, node, userKey, csrPEM string, now time.Time) (string, []byte, time.Time, error) {
	grant, granted := roleidentity.Grants[role]
	if !granted {
		return "", nil, time.Time{}, errors.New("role " + role + " has no NATS grant")
	}
	if issuer == nil || issuer.NATSKey == nil || issuer.TLSCert == nil || node == "" || !nkeys.IsValidPublicUserKey(userKey) {
		return "", nil, time.Time{}, errors.New("role credential issuer is unavailable")
	}
	csr, err := ParseCSR(csrPEM)
	if err != nil {
		return "", nil, time.Time{}, err
	}
	expires := now.Add(credentialLifetime)
	if expires.After(issuer.TLSCert.NotAfter) {
		expires = issuer.TLSCert.NotAfter
	}
	expires = expires.Truncate(time.Second)
	if expires.Sub(now) < time.Hour {
		return "", nil, time.Time{}, errors.New("host TLS issuer expires before a useful credential can be issued")
	}
	claim := jwt.NewUserClaims(userKey)
	claim.SetScoped(true)
	claim.IssuerAccount = issuer.CellAccount
	claim.Name = role + "@" + node
	claim.IssuedAt, claim.Expires = now.Unix(), expires.Unix()
	claim.Tags.Add("role:" + role)
	for _, bucket := range grant.Buckets {
		claim.Tags.Add("kv:" + bucket.Name)
	}
	for _, query := range grant.Queries {
		claim.Tags.Add("query:" + query)
	}
	for _, leaf := range grant.Observations {
		claim.Tags.Add("obs:" + leaf)
	}
	if len(grant.Queries) != 0 || len(grant.Observations) != 0 {
		claim.Tags.Add("cell:" + strings.ToLower(issuer.Cell))
	}
	signer, err := roleidentity.Signer(issuer.NATSKey)
	if err != nil {
		return "", nil, time.Time{}, err
	}
	rawJWT, err := claim.Encode(signer)
	signer.Wipe()
	if err != nil {
		return "", nil, time.Time{}, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return "", nil, time.Time{}, err
	}
	// The host issuer may name only its hosts' domain: a role is a path
	// beside the hosts' /instances/.
	leaf := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: role + "." + node},
		NotBefore: now.Add(-time.Minute), NotAfter: expires, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
		URIs: []*url.URL{{Scheme: "spiffe", Host: "hosts." + issuer.Cell + ".terrascale.internal",
			Path: "/roles/" + role + "/" + node}}}
	der, err := x509.CreateCertificate(rand.Reader, leaf, issuer.TLSCert, csr.PublicKey, issuer.TLSKey)
	if err != nil {
		return "", nil, time.Time{}, err
	}
	chain := append(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), issuer.TLSCertPEM...)
	return rawJWT, chain, expires, nil
}

roleidentity.text:
var Grants = map[string]Grant{
	// TS-633's backup shipper lease; TerraBase's NatsLeaseStore binds it.
	// TS-643's cross-region pulls: members answer terrabase-wan queries in
	// their cell and ask other cells' members over the interregion links.
	// TS-806's live stats: members answer terrabase-stats detail requests in
	// their cell and publish their rollup on their cell's obs.terrabase.
	"terrabase": {EnvPrefix: "TERRABASE_NATS_", Buckets: []Bucket{
		{Name: "terrabase_backup_leases", TTL: 15 * time.Second, History: 1, Memory: true},
	}, Queries: []string{"terrabase-wan", "terrabase-stats"}, Observations: []string{"terrabase"}},
}

// Reserved reports whether key is a launch setting the host sets for role's
// NATS identity, which a profile may not set.
func Reserved(role, key string) bool {
	grant, granted := Grants[role]
	return granted && strings.HasPrefix(key, grant.EnvPrefix)
}

// Signer derives the cell's role signing key from its host NATS issuer
// seed. Every controller holds that seed, so none needs new material, and the
// operator computes the same public key from the offline material to add
// Scope to the cell account.
func Signer(hostIssuer nkeys.KeyPair) (nkeys.KeyPair, error) {
	// Seed returns the key's own bytes: decode a copy, never clear them.
	seed, err := hostIssuer.Seed()
	if err != nil {
		return nil, err
	}
	prefix, raw, err := nkeys.DecodeSeed(seed)
	if err != nil || prefix != nkeys.PrefixByteAccount {
		return nil, errors.New("host NATS issuer seed is not an account key")
	}
	derived, err := hkdf.Key(sha256.New, raw, nil, "terrascale-role-nats-signer-v1", 32)
	clear(raw)
	if err != nil {
		return nil, err
	}
	defer clear(derived)
	return nkeys.FromRawSeed(nkeys.PrefixByteAccount, derived)
}

// Scope is the role signer's scope: a user reaches only the buckets its
// kv tags name. Tags are lowercase, so no tag can name the controllers'
// upper-case TS_ buckets.
func Scope(key string) *jwt.UserScope {
	scope := jwt.NewUserScope()
	scope.Key = key
	scope.Role = "role"
	kv := "{{tag(kv)}}"
	scope.Template.Pub.Allow = jwt.StringList{"$KV." + kv + ".>",
		"$JS.API.STREAM.INFO.KV_" + kv, "$JS.API.STREAM.MSG.GET.KV_" + kv,
		"$JS.API.DIRECT.GET.KV_" + kv, "$JS.API.DIRECT.GET.KV_" + kv + ".>"}
	// Query verbs come from the user's query tags and its own cell from its
	// cell tag; a user without a query tag gets neither subject.
	publish, subscribe := protocol.RoleQueryTemplates("{{tag(cell)}}", "{{tag(query)}}")
	scope.Template.Pub.Allow = append(scope.Template.Pub.Allow, publish)
	// A user without an obs tag gets no observation subject, as with query tags.
	scope.Template.Pub.Allow = append(scope.Template.Pub.Allow, protocol.RoleObservationTemplate("{{tag(cell)}}", "{{tag(obs)}}"))
	// ponytail: role users share NATS clients' default reply prefix, so one
	// role can see another role's JetStream replies; ts-orch's own users
	// reply on private prefixes. Template _INBOX.{{subject()}}.> once roles
	// set a private inbox prefix (TerraBase's NatsLeaseStore does not).
	scope.Template.Sub.Allow = jwt.StringList{"_INBOX.>", subscribe}
	// A member answers each query once, on the requester's reply subject.
	scope.Template.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: time.Minute}
	return scope
}

