// SamplerConfig names what a host samples.
type SamplerConfig struct {
	// CgroupRoot is the cgroup v2 directory holding one child group per
	// role or executor task. Empty skips cgroup usage.
	CgroupRoot string
	Roles      []string
	// CgroupMount bounds ancestor limit reads; defaults to /sys/fs/cgroup.
	CgroupMount string
	// Filesystems are statfs'd; the fullest one is the host's disk_util.
	Filesystems []observability.FilesystemRole
	// ReadSystem and Now are test seams; they default to /proc and the
	// wall clock.
	ReadSystem func([]observability.FilesystemRole) (observability.SystemView, error)
	Now        func() time.Time
}

func NewSampler(config SamplerConfig) *Sampler {
	if config.CgroupMount == "" {
		config.CgroupMount = "/sys/fs/cgroup"
	}
	if config.ReadSystem == nil {
		config.ReadSystem = observability.ReadSystem
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	return &Sampler{config: config, roles: make(map[string]cpuPoint)}
}

// Sample reads the host once. terrabase carries the latest verified load
// block per TerraBase role; roles without one report none. Unreadable
// sources leave their fields nil instead of failing the report.
func (s *Sampler) Sample(terrabase map[string]memberstatus.Load) Report {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.config.Now()
	report := Report{SchemaVersion: SchemaVersion}
	memTotal := uint64(0)
	if view, err := s.config.ReadSystem(s.config.Filesystems); err == nil {
		memTotal = view.MemTotalBytes
		if view.CPUCount > 0 && view.CPUCount <= MaxCPUCores {
			report.Host.CPUCores = view.CPUCount
		}
		if view.MemTotalBytes <= MaxMemoryBytes {
			report.Host.MemoryBytes = view.MemTotalBytes
		}
		busy := view.CPUSeconds.Busy()
		total := busy + view.CPUSeconds.Idle + view.CPUSeconds.IOWait
		if s.hostSeen && total > s.host.total && busy >= s.host.usage {
			report.Host.CPU = ratio(busy-s.host.usage, total-s.host.total)
		}
		s.host, s.hostSeen = cpuPoint{usage: busy, total: total, at: now}, true
		if view.MemTotalBytes > 0 && view.MemAvailBytes <= view.MemTotalBytes {
			report.Host.Memory = ratio(float64(view.MemTotalBytes-view.MemAvailBytes), float64(view.MemTotalBytes))
		}
		if finiteWithin(view.Load1, MaxLoad1) {
			load := view.Load1
			report.Host.Load1 = &load
		}
		if rx, tx := view.NetRxBytes, view.NetTxBytes; rx > 0 && tx > 0 {
			// A counter that went backwards means the interface reset, so
			// that interval has no valid rate.
			if elapsed := now.Sub(s.net.at).Seconds(); s.net.seen && elapsed > 0 && rx >= s.net.rx && tx >= s.net.tx {
				rxBps := float64(rx-s.net.rx) / elapsed
				txBps := float64(tx-s.net.tx) / elapsed
				if finiteWithin(rxBps, MaxNetworkBps) && finiteWithin(txBps, MaxNetworkBps) {
					report.Host.NetworkRxBps, report.Host.NetworkTxBps = &rxBps, &txBps
				}
			}
			s.net = netPoint{rx: rx, tx: tx, at: now, seen: true}
		}
		seen := make(map[string]bool)
		for _, filesystem := range view.Filesystems {
			if len(report.Host.Filesystems) == MaxFilesystems {
				report.Host.FilesystemsIncomplete = true
				break
			}
			if !validFilesystem(filesystem) || seen[filesystem.Role] {
				report.Host.FilesystemsIncomplete = true
				continue
			}
			seen[filesystem.Role] = true
			report.Host.Filesystems = append(report.Host.Filesystems, filesystem)
			used := ratio(float64(filesystem.SizeBytes-filesystem.AvailBytes), float64(filesystem.SizeBytes))
			if report.Host.Disk == nil || *used > *report.Host.Disk {
				report.Host.Disk = used
			}
		}
	} else {
		report.Host.FilesystemsIncomplete = true
	}
	present := make(map[string]struct{}, len(s.config.Roles))
	for _, role := range s.config.Roles {
		if len(report.Roles) == MaxRoles {
			break
		}
		usage, seen := s.sampleCgroup(role, now, memTotal)
		if seen {
			present[role] = struct{}{}
		}
		if load, ok := terrabase[role]; ok && load.Validate() == nil {
			usage.TerraBase = &load
		}
		if usage.CPUCores != nil || usage.MemoryBytes != nil || usage.TerraBase != nil {
			report.Roles = append(report.Roles, usage)
		}
	}
	// A role whose group vanished (stopped workload) restarts its CPU
	// baseline when it comes back, so a restart never reads as a burst.
	s.forgetCgroups(present)
	return report
}

aggregator.text:
func (r run) covered(now time.Time, window, warmUp, minInterval time.Duration) bool {
	allowed := max(window/2, 2*minInterval)
	if now.Sub(r.since) < warmUp || now.Sub(r.last) > allowed {
		return false
	}
	for i := len(r.holes) - 1; i >= 0 && now.Sub(r.holes[i].end) < window; i-- {
		if r.holes[i].length > allowed {
			return false
		}
	}
	return true
}

// Reset forgets every report and sample, for example when the authority
// term changes: a new term must observe a fresh window before scaling.
func (a *Aggregator) Reset() {
	a.mu.Lock()
	clear(a.nodes)
	clear(a.runs)
	a.mu.Unlock()
}

func NewAggregator(config AggregatorConfig) *Aggregator {
	if config.MinInterval <= 0 {
		config.MinInterval = DefaultMinInterval
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = DefaultStaleAfter
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	config.Requests = maps.Clone(config.Requests)
	return &Aggregator{config: config, nodes: make(map[string]*nodeState), runs: make(map[seriesKey]run)}
}

func (a *Aggregator) Read(ctx context.Context, target autoscale.Target, signal autoscale.Signal, now time.Time) (autoscale.Reading, error) {
	reading := autoscale.Reading{Signal: signal.Name}
	a.mu.Lock()
	// Warm once the run started within one minimum report interval of the
	// window's start, so a window is covered even if its first sample
	// landed a moment after the window opened; but never sooner than one
	// minimum interval, so a window as short as the report interval still
	// needs more than the first report after a reset.
	current, ok := a.runs[seriesKey{target: target, signal: signal.Name}]
	warmUp := max(signal.Window()-a.config.MinInterval, a.config.MinInterval)
	if !ok || now.Sub(current.last) > a.config.StaleAfter ||
		!current.covered(now, signal.Window(), warmUp, a.config.MinInterval) {
		a.mu.Unlock()
		return reading, nil
	}
	a.pruneLocked(a.config.Now(), nodeRetention)
	key := seriesKey{target: target, signal: signal.Name}
	stores := make([]*autoscale.WindowStore, 0, len(a.nodes))
	for _, node := range a.nodes {
		if last, ok := node.series[key]; ok && now.Sub(last) <= a.config.StaleAfter {
			stores = append(stores, node.store)
		}
	}
	a.mu.Unlock()
	values := make([]float64, 0, len(stores))
	for _, store := range stores {
		node, err := store.Read(ctx, target, signal, now)
		if err != nil {
			return autoscale.Reading{}, err
		}
		if node.Samples > 0 {
			values = append(values, node.Value)
			reading.Samples += node.Samples
		}
	}
	reading.Value = autoscale.Aggregate(signal.AggregationOrDefault(), values)
	return reading, nil
}

// Record accepts one validated report. The caller must already have
// authenticated the host and filtered Roles to roles it currently runs.
func (a *Aggregator) Record(origin Origin, report Report) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, a.config.Requests)
}

// RecordRequests normalizes one authenticated host against its actual summed
// task reservations. Other hosts keep their own requests and sample windows.
func (a *Aggregator) RecordRequests(origin Origin, report Report, requests map[string]Request) error {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.record(origin, report, requests)
}

// record is called with the aggregator lock held.
func (a *Aggregator) record(origin Origin, report Report, requests map[string]Request) error {
	if err := report.Validate(); err != nil {
		return err
	}
	now := a.config.Now()
	node, known := a.nodes[origin.Node]
	if known && now.Sub(node.latest.At) < a.config.MinInterval {
		return ErrTooFrequent
	}
	if !known {
		if len(a.nodes) >= maxNodes {
			// Full: forget every node that is no longer reporting, even if
			// a long window could still use its older samples.
			a.pruneLocked(now, a.config.StaleAfter)
		}
		if len(a.nodes) >= maxNodes {
			return ErrTooManyNodes
		}
		node = &nodeState{store: autoscale.NewWindowStore(nodeRetention, a.nodePoints()),
			series: make(map[seriesKey]time.Time)}
		a.nodes[origin.Node] = node
	}
	node.latest = NodeLoad{Origin: origin, At: now, Report: report}
	// Recording under the aggregator lock keeps one node's samples in
	// receive order and its store from being pruned mid-record.
	for _, role := range report.Roles {
		target := autoscale.Target{Cell: origin.Cell, Environment: origin.Environment, Role: role.Role}
		for name, value := range roleSignals(role, report.Host, requests[role.Role]) {
			node.store.Record(target, name, autoscale.Sample{At: now, Value: value})
			key := seriesKey{target: target, signal: name}
			node.series[key] = now
			current := a.runs[key]
			switch gap := now.Sub(current.last); {
			case current.last.IsZero() || gap > a.config.StaleAfter:
				current.since, current.holes = now, nil
			case gap > 2*a.config.MinInterval:
				// Samples arrive in receive order, so holes stay sorted and
				// the expired ones are at the front.
				expired := 0
				for expired < len(current.holes) && now.Sub(current.holes[expired].end) > nodeRetention {
					expired++
				}
				current.holes = append(current.holes[expired:], hole{end: now, length: gap})
			}
			current.last = now
			a.runs[key] = current
		}
	}
	return nil
}

func roleSignals(role RoleUsage, host HostUsage, request Request) map[autoscale.SignalName]float64 {
	signals := make(map[autoscale.SignalName]float64, 7)
	if role.CPUCores != nil && request.CPUCores > 0 {
		signals[autoscale.SignalCPUUtilization] = *role.CPUCores / request.CPUCores
	}
	if role.MemoryBytes != nil && request.MemoryBytes > 0 {
		signals[autoscale.SignalMemoryUtilization] = float64(*role.MemoryBytes) / float64(request.MemoryBytes)
	}
	if host.Disk != nil && (role.CPUCores != nil || role.MemoryBytes != nil) {
		// Disk is shared by every role of the host; it is attributed to the
		// roles that actually run there.
		signals[autoscale.SignalDiskUtilization] = *host.Disk
	}
	if load := role.TerraBase; load != nil {
		signals[autoscale.SignalTerraBaseConnectionsPerMember] = float64(load.Connections)
		signals[autoscale.SignalTerraBaseStorageBytes] = float64(load.StorageBytes)
		signals[autoscale.SignalTerraBaseReplicationLag] = float64(load.ReplicationLagSeq)
		signals[autoscale.SignalTerraBaseWriteQPS] = load.WriteQPS
	}
	return signals
}

// Nodes lists every node's latest report that is not stale, by node name.
func (a *Aggregator) Nodes() []NodeLoad {
	now := a.config.Now()
	a.mu.Lock()
	a.pruneLocked(now, nodeRetention)
	out := make([]NodeLoad, 0, len(a.nodes))
	for _, node := range a.nodes {
		if now.Sub(node.latest.At) <= a.config.StaleAfter {
			out = append(out, node.latest)
		}
	}
	a.mu.Unlock()
	slices.SortFunc(out, func(x, y NodeLoad) int { return strings.Compare(x.Origin.Node, y.Origin.Node) })
	return out
}

// pruneLocked forgets nodes silent for longer than retention; none of their
// samples can fall inside a window any more.
func (a *Aggregator) pruneLocked(now time.Time, retention time.Duration) {
	for name, node := range a.nodes {
		if now.Sub(node.latest.At) > retention {
			delete(a.nodes, name)
		}
	}
	for key, current := range a.runs {
		if now.Sub(current.last) > nodeRetention {
			delete(a.runs, key)
		}
	}
}

window.text:
// WindowStore is an in-memory bounded sample store implementing Source. A
// telemetry consumer records samples and the autoscaler reads windowed
// aggregates. Samples older than retention are discarded on write.
type WindowStore struct {
	mu        sync.Mutex
	retention time.Duration
	maxPoints int
	series    map[seriesKey][]Sample
}

// NewWindowStore bounds every series by age and by point count.
func NewWindowStore(retention time.Duration, maxPoints int) *WindowStore {
	if retention <= 0 {
		// Cover the longest window a valid policy may configure: a shorter
		// retention would silently aggregate only the window's tail.
		retention = time.Duration(maxWindowSeconds) * time.Second
	}
	if maxPoints <= 0 {
		maxPoints = 4096
	}
	return &WindowStore{retention: retention, maxPoints: maxPoints, series: make(map[seriesKey][]Sample)}
}

// Record appends one sample. Non-finite or negative values are dropped.
func (s *WindowStore) Record(target Target, signal SignalName, sample Sample) {
	if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Value < 0 || sample.At.IsZero() {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	key := seriesKey{target: target, signal: signal}
	points := append(s.series[key], sample)
	points = slices.DeleteFunc(points, func(p Sample) bool { return sample.At.Sub(p.At) > s.retention })
	if len(points) > s.maxPoints {
		points = slices.Clone(points[len(points)-s.maxPoints:])
	}
	s.series[key] = points
}

// Read aggregates the samples inside the signal window ending at now.
func (s *WindowStore) Read(_ context.Context, target Target, signal Signal, now time.Time) (Reading, error) {
	s.mu.Lock()
	var values []float64
	for _, point := range s.series[seriesKey{target: target, signal: signal.Name}] {
		if !point.At.After(now) && now.Sub(point.At) <= signal.Window() {
			values = append(values, point.Value)
		}
	}
	s.mu.Unlock()
	return Reading{Signal: signal.Name, Value: Aggregate(signal.AggregationOrDefault(), values), Samples: len(values)}, nil
}

// Aggregate reduces values; an empty input yields zero.
func Aggregate(aggregation Aggregation, values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	switch aggregation {
	case AggregateMax:
		return slices.Max(values)
	case AggregateP95:
		sorted := slices.Clone(values)
		slices.Sort(sorted)
		index := int(math.Ceil(0.95*float64(len(sorted)))) - 1
		return sorted[max(index, 0)]
	default:
		sum := 0.0
		for _, value := range values {
			sum += value
		}
		return sum / float64(len(values))
	}
}

